  const dome = `M${cx - R} ${cy} Q${cx - R} ${top} ${cx} ${top} Q${cx + R} ${top} ${cx + R} ${cy}`;
  const hem = g.pat === "scallop" ? xs.slice(1).map((x, i) => `Q${(xs[i] + x)/2} ${cy + 4*k} ${x} ${cy}`).join(" ") : `L${cx - R} ${cy}`;
  const alpha = g.pat === "clear" ? ` fill-opacity=".38"` : "";
